/**
 * Stop Videos Pipeline
 *
 * Cooperatively cancel `extract_id`: sets a Redis flag `domains.ycs.ingestion.extract.task.extract_videos`'
 * Playwright chunk loop and `ingest_to_neo4j`'s retry-pass loop poll at safe
 * checkpoints, then revokes (non-terminating) any phase/per-video task still
 * queued but not yet started. Preserves SUCCESS-state phases; idempotent
 * Qdrant upserts and Neo4j skip-on-video_id let a rerun pick up cleanly.
 *
 * 2026-09-14: no longer sends SIGTERM to already-running tasks — that
 * was observed live to wedge Celery's prefork pool (see
 * `pipeline_task.service.revoke_pipeline_phases` docstring for the
 * full incident). A task already past its last checkpoint when Stop
 * is clicked finishes that unit of work (one Playwright chunk of up
 * to 10 videos, or one Neo4j retry pass) before noticing the flag —
 * bounded, not indefinite.
 */
export const postYcsContentVideosPipelineExtractIdStopMutation = (options?: Partial<Options<PostYcsContentVideosPipelineExtractIdStopData>>): UseMutationOptions<PostYcsContentVideosPipelineExtractIdStopResponse, PostYcsContentVideosPipelineExtractIdStopError, Options<PostYcsContentVideosPipelineExtractIdStopData>> => {
    const mutationOptions: UseMutationOptions<PostYcsContentVideosPipelineExtractIdStopResponse, PostYcsContentVideosPipelineExtractIdStopError, Options<PostYcsContentVideosPipelineExtractIdStopData>> = {
        mutationFn: async (fnOptions) => {
            const { data } = await postYcsContentVideosPipelineExtractIdStop({
                ...options,
                ...fnOptions,
                throwOnError: true
            });
            return data;
        }
    };
    return mutationOptions;
};

/**
 * Wipe Videos Pipeline
 *
 * Wipe artifacts for `extract_id`, then revoke in-flight phases (wipe first, revoke second).
 * Without revoke a mid-LLM-call Phase 3 writes orphan Document nodes the next Retry's skip-check finds.
 * `__Entity__` nodes left intact — may be shared across other videos.
 *
 * Sets the cooperative-cancel flag too (best-effort — a task already
 * past its next checkpoint won't see it before the hard revoke below
 * lands anyway), but keeps `terminate=True`: unlike Stop, Wipe has a
 * correctness requirement (no orphan writes after data is deleted)
 * that cooperative-only cancellation can't guarantee — a task stuck
 * mid-LLM-call between checkpoints would otherwise finish and write
 * after the wipe already ran.
 */
export const postYcsContentVideosPipelineExtractIdWipeMutation = (options?: Partial<Options<PostYcsContentVideosPipelineExtractIdWipeData>>): UseMutationOptions<PostYcsContentVideosPipelineExtractIdWipeResponse, PostYcsContentVideosPipelineExtractIdWipeError, Options<PostYcsContentVideosPipelineExtractIdWipeData>> => {
    const mutationOptions: UseMutationOptions<PostYcsContentVideosPipelineExtractIdWipeResponse, PostYcsContentVideosPipelineExtractIdWipeError, Options<PostYcsContentVideosPipelineExtractIdWipeData>> = {
        mutationFn: async (fnOptions) => {
            const { data } = await postYcsContentVideosPipelineExtractIdWipe({
                ...options,
                ...fnOptions,
                throwOnError: true
            });
            return data;
        }
    };
    return mutationOptions;
};

